import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.1C62pOns.js";const o="/pro-agent-hub-installer/capturas/en/agentes-detalhe.png",r="/pro-agent-hub-installer/capturas/en/agentes-codigo.png",i="/pro-agent-hub-installer/capturas/en/times-fluxo.png",h="/pro-agent-hub-installer/capturas/en/chat.png",f=JSON.parse('{"title":"Agents, teams and chat","description":"","frontmatter":{},"headers":[],"relativePath":"en/interface/agentes.md","filePath":"en/interface/agentes.md","lastUpdated":1787856241000}'),l={name:"en/interface/agentes.md"};function c(d,e,g,p,m,u){return a(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="agents-teams-and-chat" tabindex="-1">Agents, teams and chat <a class="header-anchor" href="#agents-teams-and-chat" aria-label="Permalink to &quot;Agents, teams and chat&quot;">​</a></h1><h2 id="agents" tabindex="-1">Agents <a class="header-anchor" href="#agents" aria-label="Permalink to &quot;Agents&quot;">​</a></h2><p><img src="'+o+'" alt="agentes-detalhe"></p><p>An <strong>agent</strong> is a model with instructions, tools and, optionally, knowledge. It is the unit that talks and that runs.</p><h3 id="instructions-tab" tabindex="-1">Instructions tab <a class="header-anchor" href="#instructions-tab" aria-label="Permalink to &quot;Instructions tab&quot;">​</a></h3><p>This is where the agent gets its personality and its limits. Three fields, with different jobs:</p><ul><li><strong>Agent description</strong> — who it is. Goes at the start of the context.</li><li><strong>Instruction</strong> — how it should behave. This is the field that changes the result the most.</li><li><strong>Expected output</strong> — the shape of the answer, when you need something structured.</li></ul><p><strong>History</strong>: turning on <em>add history to context</em> makes the agent remember the conversation. The number of previous runs is what it carries — more history costs more tokens on every question.</p><h3 id="tools-tab" tabindex="-1">Tools tab <a class="header-anchor" href="#tools-tab" aria-label="Permalink to &quot;Tools tab&quot;">​</a></h3><p>Built-in tools (web search, Wikipedia, charts), linked MCP services and the knowledge bases it may search.</p><p>An agent can have <strong>several knowledge bases</strong>. The search happens across all of them, and the closest excerpts enter the context.</p><h3 id="code-tab" tabindex="-1">Code tab <a class="header-anchor" href="#code-tab" aria-label="Permalink to &quot;Code tab&quot;">​</a></h3><p><img src="'+r+'" alt="agentes-codigo"></p><p>Every top-level function you write here becomes a tool of the agent — the model decides when to call it by reading the name and the docstring. Write both with the reader in mind: the reader is the model.</p><div class="danger custom-block"><p class="custom-block-title">No platform function exists here</p><p>This is the only code area on the platform that runs in an <strong>empty scope</strong>. <code>db_query</code>, <code>send_email</code> and the other operations <strong>do not exist</strong> here — using them raises <code>NameError</code>. Use <code>import</code> for what you need. See <a href="/pro-agent-hub-installer/en/funcoes/agente_tool">Agent — tool code</a>.</p></div><h2 id="teams" tabindex="-1">Teams <a class="header-anchor" href="#teams" aria-label="Permalink to &quot;Teams&quot;">​</a></h2><p><img src="'+i+'" alt="times-fluxo"></p><p>A <strong>team</strong> arranges agents in a hierarchy: a coordinator that takes the question and delegates to specialists. It makes sense when a single agent would end up with instructions that are too long, or when each part needs a different model.</p><p>The <strong>Flow</strong> tab is a canvas where you build the hierarchy by dragging agents and sub-teams. Each node carries the role and the specific instructions of that member in that team — the same agent can sit in different teams with different roles.</p><h2 id="chat" tabindex="-1">Chat <a class="header-anchor" href="#chat" aria-label="Permalink to &quot;Chat&quot;">​</a></h2><p><img src="'+h+'" alt="chat"></p><p>The conversation screen. Pick an agent or a team and talk. It accepts file and image attachments when the model supports them.</p><p>It is also the place to test before automating: an agent that does not answer well in chat will not answer well inside a workflow.</p>',23)])])}const _=t(l,[["render",c]]);export{f as __pageData,_ as default};
